const mongoose = require('mongoose');
const auditPlugin = require('../../../models/plugins/auditPlugin');

/**
 * One document per client per statutory return per period, generated by the
 * daily compliance cron from each client's `compliance` settings. Reminder
 * dispatch and the CRM Compliance screens both read from here — this is the
 * single source of truth for "what is due and has it been filed".
 */
const complianceReturnSchema = new mongoose.Schema(
  {
    clientId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Client',
      required: true,
      index: true,
    },
    returnType: {
      type: String,
      enum: ['gstr1', 'gstr3b', 'itr', 'gstr9c', 'roc', 'audit'],
      required: true,
    },
    frequency: {
      type: String,
      enum: ['monthly', 'quarterly', 'yearly'],
      required: true,
    },
    // '2026-06' | '2026-Q06' | 'FY2025-26'
    periodKey: { type: String, required: true },
    periodLabel: { type: String, required: true },
    dueDate: { type: Date, required: true, index: true },
    remindFrom: { type: Date, required: true },
    status: {
      type: String,
      enum: ['pending', 'filed'],
      default: 'pending',
      index: true,
    },
    filedAt: { type: Date, default: null },
    filedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
    // GSTR-3B tax payable — set by staff; client is emailed when it changes.
    taxPayable: { type: Number, default: null, min: 0 },
    taxNotifiedAt: { type: Date, default: null },
    // Reminder bookkeeping: at most one reminder per day per return.
    lastReminderAt: { type: Date, default: null },
    filedNotifiedAt: { type: Date, default: null },
  },
  { timestamps: true }
);

complianceReturnSchema.plugin(auditPlugin, { compoundFirmIndex: false });
complianceReturnSchema.index(
  { firmId: 1, clientId: 1, returnType: 1, periodKey: 1 },
  { unique: true }
);
complianceReturnSchema.index({ firmId: 1, status: 1, dueDate: 1 });

module.exports = mongoose.model('ComplianceReturn', complianceReturnSchema);
